:root {
  --ink: #302933;
  --paper: #fffdf9;
  --line: #ded7ce;
  --plum: #6f4b70;
  --mist: #f2ebf2;
}

.tuning-card {
  box-sizing: border-box;
  width: 480px;
  padding: 18px;
  border: 1px solid var(--line);
  border-radius: 18px;
  background: var(--paper);
  color: var(--ink);
}

.card-header {
  display: flex;
  align-items: flex-start;
  justify-content: space-between;
  gap: 16px;
  padding-bottom: 14px;
  border-bottom: 1px solid var(--line);
}

.eyebrow {
  margin: 0 0 4px;
  color: var(--plum);
  font-size: 11px;
  font-weight: 700;
  letter-spacing: 1.2px;
}

h1 {
  margin: 0;
  font-size: 22px;
  line-height: 1.15;
}

.status {
  padding: 5px 9px;
  border-radius: 999px;
  background: var(--mist);
  color: var(--plum);
  font-size: 12px;
  font-weight: 700;
}

.appointment {
  display: flex;
  align-items: center;
  gap: 12px;
  padding: 14px 0;
}

.instrument-icon {
  display: grid;
  width: 42px;
  height: 42px;
  place-items: center;
  border-radius: 12px;
  background: var(--plum);
  color: var(--paper);
  font-size: 24px;
}

.details {
  display: grid;
  flex: 1;
  grid-template-columns: 1fr 1.25fr;
  gap: 12px;
}

.detail {
  display: flex;
  flex-direction: column;
  gap: 3px;
}

.detail-label {
  color: var(--plum);
  font-size: 11px;
  font-weight: 700;
  letter-spacing: 0.6px;
  text-transform: uppercase;
}

.detail-value {
  font-size: 14px;
  line-height: 1.3;
}

.notes {
  padding: 11px 12px;
  border-radius: 10px;
  background: var(--mist);
}

.notes h2 {
  margin: 0 0 3px;
  font-size: 13px;
}

.notes p {
  margin: 0;
  font-size: 13px;
  line-height: 1.4;
}

.card-footer {
  display: flex;
  align-items: center;
  justify-content: space-between;
  margin-top: 14px;
  color: var(--plum);
  font-size: 12px;
  font-weight: 700;
}

button {
  border: 0;
  border-radius: 8px;
  padding: 8px 11px;
  background: var(--plum);
  color: var(--paper);
  font-size: 12px;
  font-weight: 700;
}
